export const meta = {
  name: 'ts-token-topup-001-a2a3b',
  description: 'TS-TOKEN-TOPUP-001: dokończenie A2 (notifications table) + A3 (rate limit/cron) + B (outbox retry policy) + testing + final gate',
  phases: [
    { title: 'Infrastructure', detail: 'A2->A3 (współdzielony plik webhook controller, sekwencyjnie) równolegle z B (outbox/retry, niezależne pliki)' },
    { title: 'Testing', detail: 'L1/L2/L3 dla zmian z Infrastructure' },
    { title: 'Final Gate', detail: 'security-e2e-verifier na całości diffu' },
  ],
}

async function ask(prompt, opts) {
  try {
    return await agent(prompt, opts)
  } catch (e) {
    log(`${opts.label}: brak wyniku — ${e && e.message ? e.message : String(e)}`)
    return null
  }
}

const IMPL_SCHEMA = {
  type: 'object',
  required: ['status', 'filesChanged', 'summary'],
  properties: {
    status: { type: 'string', enum: ['DONE', 'PARTIAL', 'BLOCKED'] },
    filesChanged: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
    gaps: { type: 'string' },
  },
}

const VERIFY_SCHEMA = {
  type: 'object',
  required: ['verdict', 'violations'],
  properties: {
    verdict: { type: 'string', enum: ['GO', 'NO_GO'] },
    violations: { type: 'array', items: { type: 'string' } },
  },
}

const CHECKS_SCHEMA = {
  type: 'object',
  required: ['typecheck'],
  properties: {
    typecheck: { type: 'string', enum: ['pass', 'fail'] },
    tail: { type: 'string' },
  },
}

const GATE_SCHEMA = {
  type: 'object',
  required: ['verdict', 'findings'],
  properties: {
    verdict: { type: 'string', enum: ['GO', 'NO_GO'] },
    findings: { type: 'array', items: { type: 'string' } },
  },
}

const CARDS = args.cards || {}
const FACTS = args.facts || {}

function cardsBlock(keys) {
  return keys
    .map((k) => (CARDS[k] ? `\n=== KARTA REGUŁY: ${k} ===\n${CARDS[k]}\n=== koniec karty ===\n` : ''))
    .join('')
}

async function runUnit(unitId, basePrompt, cardKeys, agentType) {
  let silent = 0
  let lastViolations = null
  for (let attempt = 1; attempt <= 3; attempt++) {
    const prompt =
      basePrompt +
      cardsBlock(cardKeys) +
      `\n\nMasz komplet faktów i kart reguł POWYŻEJ. NIE czytaj pełnych wzorców, NIE grepuj repo w poszukiwaniu tego co już jest podane. Jeśli fakt naprawdę nie rozstrzyga Twojego przypadku — napisz to w polu "gaps" i zaimplementuj najbliższy wariant zgodny z tym, co karty mówią.` +
      (silent
        ? `\n\nUWAGA: ${silent} poprzednia(e) próba(y) tej jednostki skończyły się BEZ wyniku (budżet tur wyczerpany). Zakres jest najpewniej za duży — zrób NAJMNIEJSZY kompletny fragment i oddaj structured output, zamiast zaczynać całość od nowa. Pliki mogły zostać częściowo zmodyfikowane przez poprzednią próbę — SPRAWDŹ ich stan przed edycją, nie zakładaj czystego drzewa.`
        : '') +
      (lastViolations
        ? `\n\nPOPRAWKA — napraw dokładnie te naruszenia z poprzedniej weryfikacji:\n${lastViolations.join('\n')}`
        : '')

    const impl = await ask(prompt, {
      label: `${unitId}-impl-${attempt}`,
      phase: 'Infrastructure',
      agentType,
      maxTurns: 45,
      schema: IMPL_SCHEMA,
    })

    if (!impl) {
      if (++silent >= 2) {
        return { unitId, status: 'ESCALATE_AND_HALT', reason: 'dwa kolejne wyjścia bez structured output — zakres za duży na budżet' }
      }
      continue
    }
    silent = 0

    if (impl.status === 'BLOCKED') {
      return { unitId, status: 'ESCALATE_AND_HALT', reason: `implementer zgłosił BLOCKED: ${impl.summary} / gaps: ${impl.gaps || ''}` }
    }

    const checks = await ask(
      `W repo /opt/projects/juz-ide-api-1 uruchom: pnpm typecheck. NIC nie czytaj, nie analizuj, nie poprawiaj. Zwróć status i ostatnie 40 linii przy błędzie.`,
      { label: `${unitId}-checks-${attempt}`, phase: 'Infrastructure', effort: 'low', maxTurns: 8, schema: CHECKS_SCHEMA }
    )
    if (checks && checks.typecheck === 'fail') {
      lastViolations = [`pnpm typecheck FAIL:\n${checks.tail || ''}`]
      continue
    }

    const verify = await ask(
      `Zweryfikuj zmiany jednostki ${unitId} (TS-TOKEN-TOPUP-001, kontynuacja Faza 0+4a). Implementer zgłosił: ${impl.summary}\nPliki zmienione: ${impl.filesChanged.join(', ')}\n\n` +
        basePrompt +
        cardsBlock(cardKeys) +
        `\n\nSprawdź zgodność z kartami reguł POWYŻEJ regułę po regule, cytuj naruszenia z file:line. pnpm typecheck już przeszedł (nie uruchamiaj ponownie).`,
      { label: `${unitId}-verify-${attempt}`, phase: 'Infrastructure', agentType: 'code-quality-verifier', maxTurns: 20, schema: VERIFY_SCHEMA }
    )

    if (!verify) {
      if (++silent >= 2) {
        return { unitId, status: 'ESCALATE_AND_HALT', reason: 'weryfikator dwa razy bez wyniku' }
      }
      continue
    }
    silent = 0

    if (verify.verdict === 'GO') {
      return { unitId, status: 'GO', filesChanged: impl.filesChanged, summary: impl.summary }
    }
    lastViolations = verify.violations
  }
  return { unitId, status: 'ESCALATE_AND_HALT', reason: `3 próby wyczerpane, ostatnie naruszenia: ${(lastViolations || []).join('; ')}` }
}

phase('Infrastructure')

const A2_PROMPT = `Jednostka A2 — tabela payment_gateway_raw_notifications (TS-TOKEN-TOPUP-001, kontynuacja Fazy 0+4a).

KONTEKST: Faza 0 część A1 jest już zrobiona i NIEZACOMMITOWANA w working tree (NullPaymentGateway, rawBody:true, usunięcie mock gatewaya, webhook controller z podstawową obsługą). Pracujesz NA WIERZCHU tych zmian — przeczytaj aktualny stan plików przed edycją, nie zakładaj stanu z git log.

ZADANIE:
1. Migracja 266 (POTWIERDZONY wolny numer — 262-265 zajęte przez inne równoległe taski, NIE re-derywuj): tabela \`payment_gateway_raw_notifications\` w \`src/shared/database/migrations/266_...ts\`. Kolumny: payload_sha256, payload_redacted jsonb, headers_redacted jsonb, signature_valid boolean, received_at timestamptz + kolumny derywowane source_ip_hash, source_ip_allowlisted boolean, request_id. Partial index WHERE signature_valid = false. Zarejestruj w AVAILABLE_MIGRATIONS (migrations/index.ts) w OBU repo jeśli dotyczy (tylko to repo — juz-ide-api-1).
2. Allowlist payload_redacted (realne nazwy pól ze schematu Zod, NIE z taska/TM): orderId, extOrderId, status, totalAmount (NIE "amount"), currencyCode (NIE "currency"), localReceiptDateTime. WYKLUCZ jawnie: order.customerIp (PII) i properties[] (dowolne pary klucz/wartość od dostawcy).
3. Builder headers_redacted DOMKNIĘTY: \`toRedactedHeaders(headers): RedactedWebhookHeaders\` zwracający DOKŁADNIE 8 pól: openpayu_sig_sender, openpayu_sig_algorithm, openpayu_sig_value, openpayu_sig_content, content_type, content_length, user_agent (ucięty do 256 znaków), provider_date. Nieznane nagłówki cicho odrzucane + zliczane w unknown_header_count. Osobne typowane kolumny (nie jsonb): source_ip_hash (przez hashIdentifier() z ANONYMIZATION_SALT — NIE SecureIPExtractorService, który tylko ekstrahuje IP i nie hashuje; NIE wzorzec HMAC+pepper z user-identity.aggregate.ts, to inny cel), source_ip_allowlisted, request_id.
4. DEC21 — sampling dla signature_valid=false: NIE zapisuj 1:1 na każdą próbę. Jeden wiersz agregujący na (source_ip_hash, godzina) + licznik, zamiast pełnego wiersza per żądanie. Pełny wiersz TYLKO dla zweryfikowanych notyfikacji (signature_valid=true).
5. Integracja w payments-webhook.controller.ts: zapis wiersza notyfikacji PRZED weryfikacją podpisu (z zastosowaniem samplingu z punktu 4 dla nieudanych).
6. Tabela jest QUERY-SIDE: DATABASE_TOKEN wprost, BEZ BaseKyselyRepository, BEZ loggera (console.warn akceptowalny dla repozytoriów w tym repo — ustalona wcześniej konwencja).
7. Guardian L1 (CI blocker): asercja zamrożonego zestawu kluczy headers_redacted + fixture z cookie/authorization/x-forwarded-for niczego z nich nie produkuje.
8. BUSINESS_RULES.yaml w src/contexts/payment/ — dopisz BR-PAY-RAWNOTIF-WRITE-SAMPLING-001 (format: metadata + rules[] z {id, title, description (multi-line >), severity: MUST, layer} — wzorzec: istniejący wpis BR-PAY-OUTBOX-ATOMIC-001 w tym samym pliku).
9. Przy okazji (dług do naprawienia w tym samym PR, nie osobny task): sekcja "MOCK WEBHOOK SCHEMAS" w payment-webhook.schemas.ts jest martwa po usunięciu /webhooks/mock w Fazie 0 A1 — usuń ją.

NIE RÓB: retencji/crona (to jednostka A3), rate limitingu (to jednostka A3), usuwania ENABLE_PAID_FEATURES (świadomie POZA zakresem tego przebiegu — decyzja użytkownika, flag zostaje nietknięty).

Zwróć w polu filesChanged pełną listę ścieżek, które zmodyfikowałeś/utworzyłeś — jednostka A3 będzie na nich pracować zaraz po tobie w TYM SAMYM working tree.`

const A3_PROMPT = `Jednostka A3 — rate limit webhooka + cron retencyjny (TS-TOKEN-TOPUP-001, kontynuacja Fazy 0+4a).

KONTEKST: Jednostka A2 (tabela payment_gateway_raw_notifications) właśnie zakończyła się GO i zmodyfikowała m.in. payments-webhook.controller.ts w TYM SAMYM working tree. Przeczytaj aktualny stan tego pliku PRZED edycją — nie zakładaj stanu sprzed A2.

ZADANIE:
1. @RateLimit na POST /api/payments/webhooks/payu. RateLimitGuard jest JUŻ globalny (APP_GUARD przez SecurityModule) — NIE importuj RateLimitingModule w payments-api.module.ts, wystarczy sam dekorator. Wzorzec konfiguracji: osobny plik *.rate-limits.ts z createRateLimit({windowMs, max, message}) — patrz src/app/api/auth/auth.rate-limits.ts jako przykład. Wartość: {max: 1200, windowMs: 60_000} (mnożnik roli guest=0.5 z role-multiplier.strategy.ts daje efektywnie ~600/min — WARTOŚĆ 1200 już to uwzględnia, nie dziel ręcznie).
2. KRYTYCZNE — NIE dodawaj wzorca "/api/payments/" do CRITICAL_ENDPOINT_PATTERNS w endpoint-criticality.config.ts. To świadome odstępstwo od ogólnej reguły "rate limit fail-closed": dla tej trasy fail-closed (503 gdy Redis padnie) oznacza utracone settlementy PayU, nie obronę — ten sam błąd jest DZIŚ realny dla /api/pricing/payu/ (osobne zgłoszenie, poza zakresem). Zostaw domyślne (nie-krytyczne) zachowanie guarda dla tej trasy. Wpisz w kodzie krótki komentarz wyjaśniający DLACZEGO ta trasa świadomie NIE jest na liście krytycznych (żeby przyszły review nie "naprawił" tego przez dodanie jej tam).
3. Ręczny licznik Redis per orderId (INCR+EXPIRE, NIE przez @RateLimit — brak ekstraktora klucza w istniejącym mechanizmie dla tego przypadku): 10/min.
4. Ręczny licznik Redis nieudanych podpisów, kluczowany na source_ip_hash (ten sam hashIdentifier() co w A2): 20 nieprawidłowych podpisów w oknie 5 minut → blok + alert (logger.error z alertCode w metadanych, wzorem istniejącej konwencji FINANCIAL_RECONCILIATION_REQUIRED w token-economy-integration.processor.ts — nie buduj nowego mechanizmu dostarczania alertów, tylko trzymaj się tej samej konwencji logowania).
5. Limit body na tej trasie: 64 KB.
6. Cron retencyjny 135 dni dla payment_gateway_raw_notifications (DEC17). Wzorzec: AnonymizationCronService (src/contexts/auth/application/services/anonymization-cron.service.ts) — @Cron('0 2 * * *', {timeZone: 'Europe/Warsaw'}), @Inject(DATABASE_TOKEN) BEZPOŚREDNIO (tabela nie ma agregatu/portu — to jest dopuszczalny wyjątek RP12 z karty repository, wymaga komentarza // RP12-EXCEPTION: <powód> nad wstrzyknięciem, analogicznie do KyselyOutboxRepository), advisory lock Postgresa (pg_try_advisory_lock(hashtext($1)) / pg_advisory_unlock — operacje na JEDNYM połączeniu, bo lock jest session-scoped) z WŁASNĄ nazwaną stałą klucza locka (nie reużywaj GDPR_CRON_LOCK_KEY z auth — to inny cron, potrzebuje własnego klucza). Nowy plik w src/contexts/payment/infrastructure/scheduler/, rejestracja w PaymentModule.providers[] (ScheduleModule.forRoot() już globalny). Dead man's switch: osobna asercja/log że max(received_at) nie jest starsze niż retencja+margines — pusty wynik cronu bez błędu NIE jest dowodem że działa, potrzebny osobny sygnał.
7. NIE RUSZAJ ENABLE_PAID_FEATURES / PAID_FEATURES_ENABLED — świadoma decyzja użytkownika: ten flag steruje też MVP-fee w pricing (local-shares, service-offerings), poza zakresem tego przebiegu ("webhook hardening"). Zostaw całkowicie nietknięty, nie usuwaj, nie komentuj.
8. BUSINESS_RULES.yaml (payment) — dopisz regułę(y) dla rate-limit/retencji jeśli pasują do istniejącego formatu (wzorzec BR-PAY-OUTBOX-ATOMIC-001 w tym samym pliku).

Zwróć w filesChanged pełną listę ścieżek.`

const B_PROMPT = `Jednostka B — outbox FAILED nieterminalny + retry policy per-event (TS-TOKEN-TOPUP-001, DEC14 + DEC-F4, Priorytet #1 całego taska).

KONTEKST: Ta jednostka NIE dotyka payments-webhook.controller.ts ani tabeli notyfikacji — pracuje na osobnych plikach (outbox-poller.service.ts, queue.types.ts, integration-event-fan-out.service.ts, token-economy-integration.processor.ts). Może iść równolegle z A2/A3.

⚠️ ZMIANA WZGLĘDEM ANALIZY — zweryfikowane świeżo w kodzie: NO_ROUTE w outbox-poller.service.ts JEST JUŻ obsłużony jako osobny przypadek (dodany przez inny task, TS-INTEGRATION-EVENT-WIRING-AUDIT-001, PO napisaniu analizy tego taska) — markNoRoute(id, message), osobny cleanup 24h. Ale markNoRoute NIE loguje żadnego alertCode, tylko logger.warn. NIE zakładaj dziury z analizy — zweryfikuj aktualny stan pliku przed edycją.

ZADANIE:
1. FAILED nieterminalny (Priorytet #1, DEC14) — allowlista wiadomości finansowych (ta sama mapa co punkt 2 niżej). Dla wiadomości z allowlisty: reset FAILED → PENDING z backoffem zamiast pozostawiania jako stan terminalny, plus twardy limit ponowień całkowitych. Dla wiadomości SPOZA allowlisty: zachowanie bez zmian (FAILED zostaje terminalny) — pełna wersja "dla wszystkich 41 kolejek" należy do TS-DR-OUTBOX-002, poza zakresem tego taska.
2. Dodaj alertCode do istniejącej ścieżki markNoRoute (dziś tylko logger.warn) dla wiadomości z tej samej allowlisty finansowej — wzorem istniejącej konwencji logowania alertCode w token-economy-integration.processor.ts (pole alertCode w obiekcie logowanym przez logger.error, np. FINANCIAL_RECONCILIATION_REQUIRED). NIE buduj nowego mechanizmu dostarczania/routingu alertów — w repo nie ma odbiorcy alertCode, to znany, osobny gap.
3. DEC-F4 — nowa funkcja getEventRetryPolicy(eventName) w queue.types.ts, WZOREM istniejącej getEventJobPriority(eventName) (4-liniowa funkcja Set.has() → wartość, w tym samym pliku). Domyślnie {attempts: 5, backoff: {type:'exponential', delay: 2000}}. Dla eventów ścieżki pieniężnej: {attempts: 16, backoff: {type:'fixed', delay: 60_000}}. Allowlista ścieżki pieniężnej = MONEY_QUEUE_RETRY: PaymentCompletedIntegrationEvent.EVENT_NAME (JUŻ istnieje w CRITICAL_PRIORITY_EVENTS, potraktuj WSZYSTKIE jego wystąpienia jako pieniężne — świadomie zaakceptowana zmiana obejmuje też dzisiejszą ścieżkę subskrypcyjną, użytkownik już zatwierdził tę regresję SLA alertu z ~30s na ~15min) + placeholder na przyszłe TokenPurchase* (Faza 3 tego taska, jeszcze nie istnieją — dodaj komentarz TODO z odniesieniem do DEC-F4, nie twórz pustych stałych na wyrost).
4. Wpięcie w integration-event-fan-out.service.ts: queue.add(eventName, jobData, {...this.jobOpts, priority: getEventJobPriority(eventName), ...getEventRetryPolicy(eventName)}) — retry policy NADPISUJE attempts/backoff z jobOpts dla eventów z allowlisty, zachowując resztę jobOpts (removeOnComplete, retention itd.) bez zmian.
5. token-economy-integration.processor.ts onFailed: fallback \`job.opts?.attempts ?? 5\` daje fałszywy alarm ~11 prób za wcześnie po zmianie na attempts:16 — zamień na odczyt z faktycznej polityki (getEventRetryPolicy(eventName).attempts jako fallback zamiast literału 5).
6. NIE twórz osobnej kolejki pieniężnej — izolujemy politykę retry przez per-event mapę, nie infrastrukturę (41 kolejek dzieli jedno registerQueueAsync). NIE zmieniaj bull.module.ts defaultJobOptions (to potwierdzony no-op dla tej ścieżki — attempts:3/exponential:1000 tam jest i tak nadpisywane przez jobOpts per-job).
7. Test L1 (może być w tej jednostce jako fundament dla warstwy testing, ale PEŁNA piramida robi to osobna jednostka testing): asercja relacji REPAIR_MIN_AGE > queueHorizon(attempts, cap, jitter) + OUTBOX_RECOVERY_MAX jeśli taka stała już istnieje w repo — jeśli nie istnieje, NIE twórz jej w tej jednostce (to należy do joba naprawczego Fazy 4, poza zakresem A2/A3/B), zostaw notatkę w polu gaps.

Zwróć w filesChanged pełną listę ścieżek.`

const a2 = await runUnit('A2', A2_PROMPT, ['repository', 'security', 'logger'], 'infrastructure-implementer')
if (!a2 || a2.status !== 'GO') {
  return { escalatedAt: 'A2', a2 }
}
const a3 = await runUnit('A3', A3_PROMPT, ['repository', 'security', 'logger'], 'infrastructure-implementer')
if (!a3 || a3.status !== 'GO') {
  return { escalatedAt: 'A3', a2, a3 }
}
const chainResult = { unitId: 'A2+A3', status: 'GO', filesChanged: [...(a2.filesChanged || []), ...(a3.filesChanged || [])] }

const bResult = await runUnit('B', B_PROMPT, ['outbox', 'logger'], 'infrastructure-implementer')
if (!bResult || bResult.status !== 'GO') {
  return { escalatedAt: 'B', chainResult, bResult }
}

phase('Testing')

const TEST_WEBHOOK_PROMPT = `Piramida testów L1/L2/L3 dla jednostek A2+A3 (TS-TOKEN-TOPUP-001, kontynuacja Fazy 0+4a).

Zmienione pliki (A2+A3): ${(chainResult.filesChanged || []).join(', ')}

Zakres do przetestowania:
- Migracja 266 (payment_gateway_raw_notifications) i tabela — test że migracja się wykonuje i partial index działa.
- Builder toRedactedHeaders — test L1: zamrożony zestaw kluczy, fixture z cookie/authorization/x-forwarded-for nie produkuje nic z nich (to jest guardian, powinien już istnieć z A2 — jeśli nie, dopisz).
- Allowlist payload_redacted — L1 na realnych nazwach pól (totalAmount, currencyCode, localReceiptDateTime, orderId, extOrderId, status), asercja że customerIp i properties[] NIGDY nie trafiają do payload_redacted.
- Sampling signature_valid=false (DEC21) — L2 test że powtórzone nieudane próby z tego samego (source_ip_hash, godzina) agregują się w jeden wiersz z licznikiem, nie tworzą N wierszy.
- Rate limit na webhooku — L2 test że @RateLimit działa (429 po przekroczeniu), test że endpoint NIE jest na CRITICAL_ENDPOINT_PATTERNS (asercja negatywna — ważna, bo to świadome odstępstwo).
- Licznik nieudanych podpisów (20/5min → blok+alert) i licznik per-orderId (10/min) — L2, przez fake Redis/testcontainer wzorem istniejących testów rate-limitingu w repo.
- Cron retencyjny — L1/L2: usuwa wiersze starsze niż 135 dni, zostawia nowsze, advisory lock zapobiega równoległemu uruchomieniu (test L2 z dwoma symulowanymi instancjami jeśli wzorzec w repo na to pozwala), dead man's switch loguje/alarmuje gdy nie ma nowych usuniętych wierszy dłużej niż oczekiwano.
- BR-PAY-RAWNOTIF-WRITE-SAMPLING-001 — test że reguła jest faktycznie egzekwowana kodem, nie tylko opisana w YAML.

Piramida L1 ~50% / L2 ~30% / L3 ~20%. NIE uruchamiaj pełnej suity e2e (~55 min) — testuj tylko dodane/zmienione pliki, komenda BEZ "--" przed ścieżką pliku (pnpm test -- <plik> zeruje filtr i odpala całą suitę — znany footgun w tym repo).`

const TEST_OUTBOX_PROMPT = `Piramida testów L1/L2/L3 dla jednostki B (TS-TOKEN-TOPUP-001, DEC14+DEC-F4, kontynuacja Fazy 0+4a).

Zmienione pliki (B): ${(bResult.filesChanged || []).join(', ')}

Zakres do przetestowania:
- FAILED → PENDING reset dla allowlisty finansowej — L1 (funkcja czysta jeśli wydzielona) + L2 (symulacja wyczerpania prób w outbox-pollerze, asercja że wiadomość finansowa wraca do PENDING zamiast zostać terminalnie FAILED, a wiadomość spoza allowlisty zostaje FAILED jak dziś).
- alertCode w markNoRoute dla wiadomości finansowych — L1/L2 asercja że pole alertCode pojawia się w logu tylko dla allowlisty.
- getEventRetryPolicy(eventName) — L1: PaymentCompletedIntegrationEvent → {attempts:16, fixed 60000}, dowolny inny event → default {attempts:5, exponential 2000}.
- Wpięcie w integration-event-fan-out.service.ts — L2: queue.add faktycznie dostaje nadpisane attempts/backoff dla eventu finansowego (nie tylko priority jak dziś).
- onFailed fallback w token-economy-integration.processor.ts — L1: fallback NIE jest już literałem 5, tylko odczytany z polityki.

Piramida L1 ~50% / L2 ~30% / L3 ~20%. Komenda testów BEZ "--" przed ścieżką pliku (znany footgun w tym repo).`

const testWebhook = await runUnit('testing-webhook', TEST_WEBHOOK_PROMPT, ['logger'], 'test-implementer')
if (!testWebhook || testWebhook.status !== 'GO') {
  return { escalatedAt: 'testing-webhook', testWebhook }
}
const testOutbox = await runUnit('testing-outbox', TEST_OUTBOX_PROMPT, ['outbox', 'logger'], 'test-implementer')
if (!testOutbox || testOutbox.status !== 'GO') {
  return { escalatedAt: 'testing-outbox', testWebhook, testOutbox }
}

